def compute(vars):
    collateral_received = vars["v1"]
    collateral_used = vars["v2"]

    if collateral_received == 0:
        return None

    ratio = collateral_used / collateral_received
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "collateral_received": collateral_received,
            "collateral_sold_or_repledged": collateral_used,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
